package cli

import (
	"fmt"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func enableCmd() *cobra.Command {
	var mode string

	cmd := &cobra.Command{
		Use:   "enable",
		Short: "Enable tws in the current repository",
		Long: `Enable tws workspace mode for the current repository.

Checkout mode stores metadata under .tws/ inside the repo and adds .tws/ to
.git/info/exclude (local ignore). External mode stores metadata in a sibling
directory.

This command must be run from the main worktree (not a linked worktree).`,
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			repoRoot, err := internal.MainRepoRoot()
			if err != nil {
				return fmt.Errorf("not inside a git repository: %w", err)
			}

			switch mode {
			case "checkout":
				if err := internal.EnableCheckoutMode(repoRoot); err != nil {
					return err
				}
				fmt.Printf("Checkout mode enabled in %s\n", repoRoot)
				fmt.Println("  .tws/config.yaml — workspace config")
				fmt.Println("  .tws/features/   — feature metadata")
				fmt.Println("  .tws/state/      — workspace state")
				fmt.Println("  .git/info/exclude — .tws/ added to local ignore")
			case "external":
				if err := internal.EnableExternalMode(repoRoot); err != nil {
					return err
				}
				fmt.Printf("External mode enabled in %s\n", repoRoot)
			default:
				return fmt.Errorf("--mode is required: use 'checkout' or 'external'")
			}
			return nil
		},
	}

	cmd.Flags().StringVar(&mode, "mode", "", "Workspace mode: checkout, external (required)")
	_ = cmd.MarkFlagRequired("mode")
	_ = cmd.RegisterFlagCompletionFunc("mode", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return []string{"checkout", "external"}, cobra.ShellCompDirectiveNoFileComp
	})

	return cmd
}

func modeCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "mode",
		Short: "Show current workspace mode",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			fmt.Println(ws.Mode)
			return nil
		},
	}
}

package cli

import (
	"fmt"
	"os"
	"path/filepath"

	skills "github.com/jdbencardinop/tesseraworkspaces/assets/skills"
	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func initCmd() *cobra.Command {
	var agent string
	var force bool
	var mode string
	var register bool

	cmd := &cobra.Command{
		Use:   "init",
		Short: "Install agent skills into current repo",
		Long: `Installs the tesseraworkspaces agent skill into the current repo.

Detects Claude Code or GitHub Copilot and installs the appropriate file.
Use --agent to override detection. Use --mode to set workspace_mode.`,
		RunE: func(cmd *cobra.Command, args []string) error {
			cwd, err := os.Getwd()
			if err != nil {
				return err
			}

			// --register with checkout mode should fail early.
			if register && mode == "checkout" {
				return fmt.Errorf("--register is not supported with --mode checkout: workspace registry is not yet implemented")
			}

			// Even without checkout, --register is not implemented.
			if register {
				return fmt.Errorf("--register is not yet implemented; workspace registry is planned for a future release")
			}

			// Set workspace_mode if --mode is specified.
			if mode != "" {
				repoRoot, err := internal.MainRepoRoot()
				if err != nil {
					return fmt.Errorf("not inside a git repository: %w", err)
				}
				if err := enableWorkspaceMode(repoRoot, mode); err != nil {
					return err
				}
			}

			// Agent skill installation
			detected := detectAgent(cwd)
			target := agent
			if target == "" {
				target = detected
			}

			switch target {
			case "claude":
				installFile(filepath.Join(cwd, ".claude", "skills", "tesseraworkspaces", "SKILL.md"), skills.ClaudeSkill, force)
			case "copilot":
				installFile(filepath.Join(cwd, ".github", "copilot-instructions.md"), skills.CopilotSkill, force)
			default:
				installFile(filepath.Join(cwd, ".claude", "skills", "tesseraworkspaces", "SKILL.md"), skills.ClaudeSkill, force)
			}
			return nil
		},
	}

	cmd.Flags().StringVar(&agent, "agent", "", "Agent type: claude, copilot (default: auto-detect)")
	cmd.Flags().BoolVarP(&force, "force", "f", false, "Overwrite existing skill file")
	cmd.Flags().StringVar(&mode, "mode", "", "Set workspace mode: external, checkout")
	cmd.Flags().BoolVar(&register, "register", false, "Register this workspace in the global registry (not yet implemented)")

	return cmd
}

// enableWorkspaceMode delegates to the unified internal helpers.
// Both init and enable use the same code path.
func enableWorkspaceMode(repoRoot, mode string) error {
	switch mode {
	case "checkout":
		if err := internal.EnableCheckoutMode(repoRoot); err != nil {
			return err
		}
		fmt.Printf("Workspace mode set to: %s\n", mode)
		return nil
	case "external":
		if err := internal.EnableExternalMode(repoRoot); err != nil {
			return err
		}
		fmt.Printf("Workspace mode set to: %s\n", mode)
		return nil
	default:
		return fmt.Errorf("invalid mode %q; supported: external, checkout", mode)
	}
}

// addGitExclude adds a pattern to .git/info/exclude idempotently.
// Delegates to the unified internal helper.
func addGitExclude(repoRoot, pattern string) error {
	return internal.AddGitLocalExclude(repoRoot, pattern)
}

func detectAgent(dir string) string {
	if _, err := os.Stat(filepath.Join(dir, ".claude")); err == nil {
		return "claude"
	}
	if _, err := os.Stat(filepath.Join(dir, ".github", "copilot-instructions.md")); err == nil {
		return "copilot"
	}
	return "claude"
}

func installFile(relPath string, content []byte, force bool) bool {
	if _, err := os.Stat(relPath); err == nil && !force {
		fmt.Printf("  exists: %s (use --force to overwrite)\n", relPath)
		return false
	}

	if err := os.MkdirAll(filepath.Dir(relPath), 0755); err != nil {
		fmt.Printf("  error: could not create directory for %s: %v\n", relPath, err)
		return false
	}

	if err := os.WriteFile(relPath, content, 0644); err != nil {
		fmt.Printf("  error: could not write %s: %v\n", relPath, err)
		return false
	}

	fmt.Printf("  installed: %s\n", relPath)
	return true
}

package cli

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func listCmd() *cobra.Command {
	return &cobra.Command{
		Use:     "list",
		Aliases: []string{"ls"},
		Short:   "List features and branches",
		Args:    cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				// Fallback to legacy TwsRoot for external mode compat.
				wsRoot := internal.TwsRoot()
				if _, serr := os.Stat(wsRoot); os.IsNotExist(serr) {
					fmt.Println("No workspace found. Use 'tws init --mode checkout' or 'tws enable --mode checkout'.")
					return nil
				}
				// Build a minimal workspace for listing.
				ws = internal.Workspace{MetadataRoot: wsRoot, Mode: internal.ModeExternal}
			}

			features, listErr := ws.ListFeaturesResolved()
			if listErr != nil {
				return listErr
			}

			if len(features) == 0 {
				fmt.Println("No features found. Use 'tws add <feature>' to create one.")
				return nil
			}

			fmt.Printf("Workspace: %s (mode: %s)\n\n", ws.MetadataRoot, ws.Mode)

			for _, feature := range features {
				featurePath, resolveErr := ws.ResolveFeaturePath(feature)
				if resolveErr != nil {
					// Ambiguity error — report it inline.
					fmt.Printf("%s\n  ERROR: %v\n\n", feature, resolveErr)
					continue
				}

				fmt.Printf("%s\n", feature)

				stack, serr := internal.LoadStack(featurePath)
				if serr == nil && len(stack.Branches) > 0 {
					for i, entry := range stack.Branches {
						wtPath := filepath.Join(featurePath, "worktrees", entry.Name)
						status := "active"
						if _, err := os.Stat(wtPath); os.IsNotExist(err) {
							if internal.IsPrunableWorktree(entry.Name) {
								status = "missing"
							} else {
								status = "archived"
							}
						}

						tmuxTag := ""
						session := sanitizeSessionName(feature + "/" + entry.Name)
						if sessionExists(session) {
							tmuxTag = " [tmux]"
						}

						healthTag := ""
						if status == "active" {
							if issue := internal.CheckWorktreeBranch(wtPath, entry.Name); issue != nil {
								healthTag = " [wrong-branch!]"
							}
						}

						connector := "├──"
						if i == len(stack.Branches)-1 {
							connector = "└──"
						}
						fmt.Printf("  %s %s (base: %s) [%s]%s%s\n", connector, entry.Name, entry.Base, status, tmuxTag, healthTag)
					}
				} else {
					wtDir := filepath.Join(featurePath, "worktrees")
					wts, rErr := os.ReadDir(wtDir)
					if rErr != nil || len(wts) == 0 {
						fmt.Println("  (no branches)")
					} else {
						for i, wt := range wts {
							if !wt.IsDir() {
								continue
							}
							connector := "├──"
							if i == len(wts)-1 {
								connector = "└──"
							}
							fmt.Printf("  %s %s\n", connector, wt.Name())
						}
					}
				}
				fmt.Println()
			}
			return nil
		},
	}
}

package cli

import (
	"fmt"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func migrateLayoutCmd() *cobra.Command {
	var all bool

	cmd := &cobra.Command{
		Use:   "migrate-layout [feature]",
		Short: "Migrate features from legacy to new checkout layout",
		Long: `Migrate feature directories from legacy layout (.tws/<feature>) to new
layout (.tws/features/<feature>).

Use --all to migrate all legacy features at once with preflight collision
checks and rollback on failure. Without --all, specify a single feature name.

Rejects symlinks, unsafe feature names, and path traversal attempts.
Idempotent: already-migrated features are skipped.`,
		Args: cobra.MaximumNArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			ws, err := internal.RequireWorkspace()
			if err != nil || ws.Mode != internal.ModeCheckout || len(args) > 0 {
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
			return ws.LegacyFeatureNames(), cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			if ws.Mode != internal.ModeCheckout {
				return fmt.Errorf("migrate-layout requires checkout mode (current: %s)", ws.Mode)
			}

			if all {
				result := internal.MigrateAllFeatures(ws)
				for _, name := range result.Migrated {
					fmt.Printf("  migrated: %s\n", name)
				}
				for _, name := range result.Skipped {
					fmt.Printf("  skipped (already migrated): %s\n", name)
				}
				if len(result.Errors) > 0 {
					for _, e := range result.Errors {
						fmt.Printf("  error: %s\n", e)
					}
					return fmt.Errorf("migration failed with %d error(s)", len(result.Errors))
				}
				if len(result.Migrated) == 0 && len(result.Skipped) == 0 {
					fmt.Println("Nothing to migrate.")
				}
				return nil
			}

			if len(args) == 0 {
				return fmt.Errorf("specify a feature name or use --all")
			}

			if err := internal.MigrateFeatureLayout(ws, args[0]); err != nil {
				return err
			}
			fmt.Printf("Migrated %s to new layout.\n", args[0])
			return nil
		},
	}

	cmd.Flags().BoolVar(&all, "all", false, "Migrate all legacy features")

	return cmd
}

package internal

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// EnableCheckoutMode is the single, error-returning helper that both
// `tws init --mode checkout` and `tws enable --mode checkout` use.
// It:
//  1. Validates that repoRoot is the main worktree (rejects linked worktrees).
//  2. Creates .tws/, .tws/features/, .tws/state/ idempotently.
//  3. Writes/updates .tws/config.yaml preserving existing values.
//  4. Adds .tws/ to .git/info/exclude idempotently.
func EnableCheckoutMode(repoRoot string) error {
	if err := RejectLinkedWorktree(repoRoot); err != nil {
		return err
	}

	twsDir := filepath.Join(repoRoot, ".tws")
	featuresDir := filepath.Join(twsDir, "features")
	stateDir := filepath.Join(twsDir, "state")

	for _, d := range []string{twsDir, featuresDir, stateDir} {
		if err := os.MkdirAll(d, 0755); err != nil {
			return fmt.Errorf("creating %s: %w", d, err)
		}
	}

	configPath := filepath.Join(twsDir, "config.yaml")
	cfg := LoadRepoConfig(configPath)
	cfg.WorkspaceMode = "checkout"
	if err := SaveRepoConfig(configPath, cfg); err != nil {
		return fmt.Errorf("writing config: %w", err)
	}

	if err := AddGitLocalExclude(repoRoot, ".tws/"); err != nil {
		return fmt.Errorf("updating git exclude: %w", err)
	}

	return nil
}

// EnableExternalMode writes config for external mode without creating
// checkout-specific directories.
func EnableExternalMode(repoRoot string) error {
	if err := RejectLinkedWorktree(repoRoot); err != nil {
		return err
	}

	twsDir := filepath.Join(repoRoot, ".tws")
	if err := os.MkdirAll(twsDir, 0755); err != nil {
		return fmt.Errorf("creating %s: %w", twsDir, err)
	}

	configPath := filepath.Join(twsDir, "config.yaml")
	cfg := LoadRepoConfig(configPath)
	cfg.WorkspaceMode = "external"
	return SaveRepoConfig(configPath, cfg)
}

// AddGitLocalExclude adds a pattern to .git/info/exclude idempotently.
// Returns an error if .git is a file (linked worktree) rather than a directory.
func AddGitLocalExclude(repoRoot, pattern string) error {
	gitPath := filepath.Join(repoRoot, ".git")
	info, err := os.Lstat(gitPath)
	if err != nil {
		return fmt.Errorf(".git not found in %s: %w", repoRoot, err)
	}
	if !info.IsDir() {
		return fmt.Errorf(".git is a file (linked worktree); exclude must be set from the main worktree")
	}

	excludeDir := filepath.Join(repoRoot, ".git", "info")
	if err := os.MkdirAll(excludeDir, 0755); err != nil {
		return err
	}
	excludePath := filepath.Join(excludeDir, "exclude")

	// Check if already present.
	if f, err := os.Open(excludePath); err == nil {
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
			if strings.TrimSpace(scanner.Text()) == pattern {
				f.Close() //nolint:errcheck
				return nil
			}
		}
		f.Close() //nolint:errcheck
	}

	// Read existing to check trailing newline.
	existing, _ := os.ReadFile(excludePath)

	f, err := os.OpenFile(excludePath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		return err
	}
	defer f.Close() //nolint:errcheck

	if len(existing) > 0 && !strings.HasSuffix(string(existing), "\n") {
		_, _ = f.WriteString("\n")
	}
	_, err = f.WriteString(pattern + "\n")
	return err
}

// RejectLinkedWorktree checks that repoRoot contains a .git directory
// (not a .git file, which indicates a linked worktree).
func RejectLinkedWorktree(repoRoot string) error {
	gitPath := filepath.Join(repoRoot, ".git")
	info, err := os.Lstat(gitPath)
	if err != nil {
		return fmt.Errorf("cannot stat .git in %s: %w", repoRoot, err)
	}
	if !info.IsDir() {
		return fmt.Errorf("%s is a linked worktree (.git is a file); enable must be run from the main worktree", repoRoot)
	}
	return nil
}

package internal

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

func initGitRepo(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	cmd := exec.Command("git", "-C", dir, "init", "--initial-branch=main")
	cmd.Env = append(os.Environ(), "GIT_CONFIG_NOSYSTEM=1", "HOME="+dir)
	if err := cmd.Run(); err != nil {
		t.Fatalf("git init: %v", err)
	}
	return dir
}

func TestEnableCheckoutMode_CreatesLayout(t *testing.T) {
	dir := initGitRepo(t)

	if err := EnableCheckoutMode(dir); err != nil {
		t.Fatal(err)
	}

	// Verify directories.
	for _, sub := range []string{".tws", ".tws/features", ".tws/state"} {
		path := filepath.Join(dir, sub)
		info, err := os.Stat(path)
		if err != nil {
			t.Errorf("expected %s to exist: %v", sub, err)
		} else if !info.IsDir() {
			t.Errorf("expected %s to be a directory", sub)
		}
	}

	// Verify config.
	data, err := os.ReadFile(filepath.Join(dir, ".tws", "config.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(data), "workspace_mode: checkout") {
		t.Errorf("config missing workspace_mode: checkout, got: %s", data)
	}

	// Verify git exclude.
	exclude, err := os.ReadFile(filepath.Join(dir, ".git", "info", "exclude"))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(exclude), ".tws/") {
		t.Errorf("exclude missing .tws/, got: %s", exclude)
	}
}

func TestEnableCheckoutMode_Idempotent(t *testing.T) {
	dir := initGitRepo(t)

	// Enable twice.
	if err := EnableCheckoutMode(dir); err != nil {
		t.Fatal(err)
	}
	if err := EnableCheckoutMode(dir); err != nil {
		t.Fatal(err)
	}

	// Exclude should not be duplicated.
	data, _ := os.ReadFile(filepath.Join(dir, ".git", "info", "exclude"))
	count := strings.Count(string(data), ".tws/")
	if count != 1 {
		t.Errorf("expected exactly 1 .tws/ in exclude, got %d", count)
	}
}

func TestEnableCheckoutMode_PreservesConfig(t *testing.T) {
	dir := initGitRepo(t)

	// Write config with branch_prefix first.
	twsDir := filepath.Join(dir, ".tws")
	if err := os.MkdirAll(twsDir, 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(twsDir, "config.yaml"), []byte("branch_prefix: ws/\n"), 0644); err != nil {
		t.Fatal(err)
	}

	if err := EnableCheckoutMode(dir); err != nil {
		t.Fatal(err)
	}

	data, _ := os.ReadFile(filepath.Join(twsDir, "config.yaml"))
	if !strings.Contains(string(data), "branch_prefix: ws/") {
		t.Errorf("branch_prefix not preserved: %s", data)
	}
	if !strings.Contains(string(data), "workspace_mode: checkout") {
		t.Errorf("workspace_mode not set: %s", data)
	}
}

func TestEnableCheckoutMode_RejectsLinkedWorktree(t *testing.T) {
	dir := initGitRepo(t)

	// Create initial commit so we can add worktrees.
	cmd := exec.Command("git", "-C", dir, "commit", "--allow-empty", "-m", "init")
	cmd.Env = append(os.Environ(), "GIT_CONFIG_NOSYSTEM=1", "HOME="+dir,
		"GIT_AUTHOR_NAME=test", "GIT_AUTHOR_EMAIL=t@t.com",
		"GIT_COMMITTER_NAME=test", "GIT_COMMITTER_EMAIL=t@t.com")
	if err := cmd.Run(); err != nil {
		t.Skipf("git commit failed: %v", err)
	}

	wtDir := filepath.Join(t.TempDir(), "wt")
	cmd = exec.Command("git", "-C", dir, "worktree", "add", wtDir, "-b", "wt-branch")
	cmd.Env = append(os.Environ(), "GIT_CONFIG_NOSYSTEM=1", "HOME="+dir)
	if err := cmd.Run(); err != nil {
		t.Skipf("git worktree add: %v", err)
	}

	err := EnableCheckoutMode(wtDir)
	if err == nil {
		t.Fatal("expected error for linked worktree")
	}
	if !strings.Contains(err.Error(), "linked worktree") {
		t.Errorf("expected linked worktree error, got: %v", err)
	}
}

func TestEnableCheckoutMode_SubdirResolvesRoot(t *testing.T) {
	dir := initGitRepo(t)

	// Create a subdir and try to enable from the resolved repo root.
	subdir := filepath.Join(dir, "sub", "deep")
	if err := os.MkdirAll(subdir, 0755); err != nil {
		t.Fatal(err)
	}

	// MainRepoRootIn should resolve to dir.
	root, err := MainRepoRootIn(subdir)
	if err != nil {
		t.Fatal(err)
	}
	if err := EnableCheckoutMode(root); err != nil {
		t.Fatal(err)
	}

	// Verify it was created at the repo root, not the subdir.
	if _, err := os.Stat(filepath.Join(dir, ".tws", "features")); err != nil {
		t.Errorf("expected .tws/features at repo root: %v", err)
	}
}

func TestEnableExternalMode_DoesNotCreateCheckoutDirs(t *testing.T) {
	dir := initGitRepo(t)

	if err := EnableExternalMode(dir); err != nil {
		t.Fatal(err)
	}

	// features/ and state/ should NOT exist for external mode.
	if _, err := os.Stat(filepath.Join(dir, ".tws", "features")); err == nil {
		t.Error("external mode should not create .tws/features")
	}
	if _, err := os.Stat(filepath.Join(dir, ".tws", "state")); err == nil {
		t.Error("external mode should not create .tws/state")
	}
}

func TestAddGitLocalExclude_IdempotentMultipleCalls(t *testing.T) {
	dir := initGitRepo(t)

	for i := 0; i < 3; i++ {
		if err := AddGitLocalExclude(dir, ".tws/"); err != nil {
			t.Fatal(err)
		}
	}

	data, _ := os.ReadFile(filepath.Join(dir, ".git", "info", "exclude"))
	count := strings.Count(string(data), ".tws/")
	if count != 1 {
		t.Errorf("expected 1 occurrence of .tws/, got %d in: %s", count, data)
	}
}

package internal

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
)

// MigrateResult describes the outcome of a migration run.
type MigrateResult struct {
	Migrated []string // features successfully moved
	Skipped  []string // features already in new layout
	Errors   []string // rollback/failure messages
}

// MigrateFeatureLayout migrates a single feature from legacy (.tws/<name>)
// to new layout (.tws/features/<name>). Returns an error if:
//   - feature name is invalid/unsafe
//   - source is a symlink
//   - destination already exists (collision)
//   - move fails
func MigrateFeatureLayout(ws Workspace, feature string) error {
	if err := validateFeatureName(feature); err != nil {
		return err
	}

	src := filepath.Join(ws.MetadataRoot, feature)
	dst := filepath.Join(ws.MetadataRoot, "features", feature)

	// Reject symlinks at source.
	info, err := os.Lstat(src)
	if err != nil {
		return fmt.Errorf("source %s does not exist: %w", src, err)
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("source %s is a symlink; refusing to migrate", src)
	}
	if !info.IsDir() {
		return fmt.Errorf("source %s is not a directory", src)
	}

	// Check destination collision.
	if _, err := os.Lstat(dst); err == nil {
		return fmt.Errorf("destination %s already exists (collision)", dst)
	}

	// Ensure features/ parent exists.
	if err := os.MkdirAll(filepath.Dir(dst), 0755); err != nil {
		return fmt.Errorf("creating features dir: %w", err)
	}

	return os.Rename(src, dst)
}

// MigrateAllFeatures migrates all legacy features to the new layout.
// Preflight: checks ALL sources and destinations before moving any.
// On failure mid-run: best-effort rollback of previously moved features.
func MigrateAllFeatures(ws Workspace) MigrateResult {
	result := MigrateResult{}

	if ws.Mode != ModeCheckout {
		result.Errors = append(result.Errors, "migrate-layout requires checkout mode")
		return result
	}

	// Discover legacy candidates (dirs in MetadataRoot that are not reserved).
	entries, err := os.ReadDir(ws.MetadataRoot)
	if err != nil {
		result.Errors = append(result.Errors, fmt.Sprintf("reading %s: %v", ws.MetadataRoot, err))
		return result
	}

	var candidates []string
	for _, e := range entries {
		if !e.IsDir() || isReservedDir(e.Name()) {
			continue
		}
		candidates = append(candidates, e.Name())
	}
	sort.Strings(candidates)

	if len(candidates) == 0 {
		return result
	}

	// --- Preflight: check all sources and destinations ---
	type migration struct {
		name string
		src  string
		dst  string
	}
	var migrations []migration

	for _, name := range candidates {
		src := filepath.Join(ws.MetadataRoot, name)
		dst := filepath.Join(ws.MetadataRoot, "features", name)

		// Reject symlinks.
		info, err := os.Lstat(src)
		if err != nil {
			result.Errors = append(result.Errors, fmt.Sprintf("stat %s: %v", src, err))
			continue
		}
		if info.Mode()&os.ModeSymlink != 0 {
			result.Errors = append(result.Errors, fmt.Sprintf("%s is a symlink; skipped", src))
			continue
		}

		// Check if already migrated (exists under features/).
		if _, err := os.Lstat(dst); err == nil {
			result.Skipped = append(result.Skipped, name)
			continue
		}

		migrations = append(migrations, migration{name: name, src: src, dst: dst})
	}

	// If any preflight errors detected, abort without moving anything.
	if len(result.Errors) > 0 {
		return result
	}

	// Ensure features/ exists.
	featuresDir := filepath.Join(ws.MetadataRoot, "features")
	if err := os.MkdirAll(featuresDir, 0755); err != nil {
		result.Errors = append(result.Errors, fmt.Sprintf("creating features dir: %v", err))
		return result
	}

	// --- Execute moves with rollback on failure ---
	var moved []migration
	for _, m := range migrations {
		if err := os.Rename(m.src, m.dst); err != nil {
			result.Errors = append(result.Errors, fmt.Sprintf("moving %s: %v", m.name, err))
			// Best-effort rollback.
			for _, done := range moved {
				if rbErr := os.Rename(done.dst, done.src); rbErr != nil {
					result.Errors = append(result.Errors, fmt.Sprintf("rollback %s failed: %v", done.name, rbErr))
				}
			}
			return result
		}
		moved = append(moved, m)
		result.Migrated = append(result.Migrated, m.name)
	}

	return result
}

